using LMS_BE.Data;using LMS_BE.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;
namespace LMS_BE.Controllers;
[Route("api/analytics")]
public class AnalyticsController(ApplicationDbContext db):LmsControllerBase(db){
 public record ActivityRequest(Guid? LessonId,string ActivityType,int DurationSeconds);
 [HttpPost("activity")][Authorize(Roles="Student")]public async Task<IActionResult> Activity(ActivityRequest x){if(x.DurationSeconds<0||x.DurationSeconds>86400)return BadRequest();if(x.LessonId.HasValue&&!await Db.Lessons.AnyAsync(l=>l.Id==x.LessonId&&l.Module!.Course!.Classes.Any(c=>c.Enrollments.Any(e=>e.StudentId==CurrentUserId))))return Forbid();Db.LearningActivities.Add(new LearningActivity{StudentId=CurrentUserId,LessonId=x.LessonId,ActivityType=x.ActivityType,DurationSeconds=x.DurationSeconds});await Db.SaveChangesAsync();return Ok();}
 [HttpGet("me")]public async Task<IActionResult> Me(){var from=DateTimeOffset.UtcNow.AddDays(-7);var acts=await Db.LearningActivities.Where(a=>a.StudentId==CurrentUserId&&a.OccurredAt>=from).ToListAsync();return Ok(new{ActivityCount=acts.Count,StudyMinutes=acts.Sum(a=>a.DurationSeconds)/60,LastActivity=acts.OrderByDescending(a=>a.OccurredAt).FirstOrDefault()?.OccurredAt});}
 [HttpGet("risks/class/{classId:guid}")][Authorize(Roles="Admin,Teacher")]public async Task<IActionResult> Risks(Guid classId){var c=await Db.CourseClasses.FindAsync(classId);if(c==null)return NotFound();if(!IsAdmin&&c.InstructorId!=CurrentUserId)return Forbid();return Ok(await Db.RiskPredictions.Where(r=>r.ClassId==classId).OrderByDescending(r=>r.PredictedAt).Select(r=>new{r.StudentId,Student=r.Student!.FullName,r.RiskScore,r.RiskLevel,r.Explanation,r.PredictedAt}).ToListAsync());}
 [HttpPost("risks/class/{classId:guid}/recalculate")][Authorize(Roles="Admin,Teacher")]public async Task<IActionResult> Recalculate(Guid classId){var c=await Db.CourseClasses.FindAsync(classId);if(c==null)return NotFound();if(!IsAdmin&&c.InstructorId!=CurrentUserId)return Forbid();var ids=await Db.Enrollments.Where(e=>e.ClassId==classId).Select(e=>e.StudentId).ToListAsync();var cutoff=DateTimeOffset.UtcNow.AddDays(-14);foreach(var id in ids){var scores=await Db.Submissions.Where(s=>s.StudentId==id&&s.Assessment!.CourseId==c.CourseId&&s.Score.HasValue&&s.Assessment.MaxScore>0).Select(s=>new{s.Score,s.Assessment!.MaxScore}).ToListAsync();var avg=scores.Count==0?0.5m:scores.Average(s=>s.Score!.Value/s.MaxScore);var minutes=await Db.LearningActivities.Where(a=>a.StudentId==id&&a.OccurredAt>=cutoff&&a.LessonId.HasValue&&a.Lesson!.Module!.CourseId==c.CourseId).SumAsync(a=>(int?)a.DurationSeconds)??0;var inactivity=minutes<1800?0.25m:minutes<7200?0.12m:0m;var risk=Math.Clamp((1-avg)*0.75m+inactivity,0m,1m)*100m;Db.RiskPredictions.Add(new RiskPrediction{StudentId=id,ClassId=classId,RiskScore=Math.Round(risk,2),RiskLevel=risk>=70?"High":risk>=40?"Medium":"Low",Explanation="Baseline rule: normalized grades (75%) and study activity (25%). Missing grades use neutral 50%."});}await Db.SaveChangesAsync();return Ok(new{Students=ids.Count,Model="rule-based baseline"});}
}
